"""Smoke and content tests for notice-generators.html.

Usage: PLAYWRIGHT_BROWSERS_PATH=/opt/pw-browsers python3 test_ng.py <served tree dir> <screenshot dir>

Serves the tree on port 8765 (absolute /assets paths then work unchanged), pre-sets the
consent record so the banner does not intercept clicks, and checks:
  1. no page errors or console errors on load;
  2. every scenario builds, and no generated sentence contains a WP260 qualifier
     ("may", "might", "some", "often", "possible"), "undefined", "[object", "NaN" or an em dash;
  3. scenario-specific expectations (rows, sections, the prohibited-use banner);
  4. the UI: tabs, hash routing, conditional fields, repeaters, live output, downloads,
     Save, Clear, Load, Forget;
  5. no horizontal overflow at 390px; screenshots for a visual check.
"""
import json, os, re, sys, threading, http.server, socketserver, functools
from playwright.sync_api import sync_playwright

ROOT, SHOTS = "/tmp/_r", "/tmp/_s"
os.makedirs(SHOTS, exist_ok=True)
PORT = 8765
EM = chr(0x2014)
BAD = re.compile(r"\b(may|might|some|often|possible|possibly|undefined|NaN)\b|\[object", re.I)

Handler = functools.partial(http.server.SimpleHTTPRequestHandler, directory=ROOT)
class Quiet(Handler.func):
    def log_message(self, *a): pass
socketserver.TCPServer.allow_reuse_address = True
srv = socketserver.TCPServer(("127.0.0.1", 0), functools.partial(Quiet, directory=ROOT))
PORT = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()

fails = []
def check(cond, msg):
    print(("PASS " if cond else "FAIL ") + msg)
    if not cond: fails.append(msg)

